/**
 * DynamicBody - Physics body with navigation capabilities.
 *
 * Automatically used for BodyType.DYNAMIC bodies.
 * Provides navigation methods that communicate with the physics worker.
 */
export class DynamicBody extends Body {
    /**
     * Create a dynamic body with navigation support.
     *
     * @param {Object} views - Physics views object containing type-indexed body arrays.
     * @param {string} type - Body type (should be 'dynamic').
     * @param {number} index - Body index in the views array.
     * @param {THREE.Object3D|null} entity - Optional entity to sync transforms to.
     * @param {Object} physics - Physics instance for worker communication.
     */
    constructor(views: any, type: string, index: number, entity: THREE.Object3D | null, physics: any);
    /**
     * Three.js-style type flag. True for DynamicBody instances.
     * @type {boolean}
     * @readonly
     */
    readonly isDynamicBody: boolean;
    /**
     * Lazy getter for SharedArrayBuffer view.
     * Returns the view for this body's index.
     * @private
     */
    private _getView;
    /**
     * Lazy-initialized Navigation instance.
     * @type {Navigation|null}
     * @private
     */
    private _navigation;
    /**
     * Camera instance for this body (for spectating/multiplayer).
     * @type {Object|null}
     * @private
     */
    private _camera;
    /**
     * Navigation interface for pathfinding.
     *
     * Provides BASIC (straight-line) and A* pathfinding navigation.
     * BASIC mode requires no setup - just call navigateTo().
     * A* mode requires a PathfindingGrid via enable().
     *
     * @type {Navigation}
     * @readonly
     *
     * @example
     * // BASIC mode - no setup required
     * playerBody.navigation.navigateTo(clickPosition);
     *
     * // A* mode with PathfindingGrid
     * await playerBody.navigation.enable(grid, { maxSpeed: 5 });
     * playerBody.navigation.navigateTo(targetPosition);
     *
     * // Check state
     * if (playerBody.navigation.isNavigating) { ... }
     *
     * // Stop navigation
     * playerBody.navigation.stop();
     */
    readonly get navigation(): Navigation;
    /**
     * Alias for navigation (backwards compatibility).
     * @type {Navigation}
     * @readonly
     * @deprecated Use navigation instead
     */
    readonly get pathfinder(): Navigation;
    /**
     * Set camera instance for this body.
     *
     * @param {Object|null} cam - Camera instance
     */
    set camera(cam: any | null);
    /**
     * Get camera instance for this body.
     * Used for spectating and multiplayer scenarios.
     *
     * @returns {Object|null} Camera instance or null
     */
    get camera(): any | null;
    set collidesWithDynamic(value: boolean);
    /**
     * Whether this body collides with other dynamic bodies.
     *
     * Enabled by default. Disable for performance optimization when
     * Dynamic ↔ Dynamic collision is not needed for specific bodies.
     *
     * @type {boolean}
     *
     * @example
     * // Disable D↔D collision for a background NPC
     * npcBody.collidesWithDynamic = false;
     *
     * // Check current state
     * if (playerBody.collidesWithDynamic) { ... }
     */
    get collidesWithDynamic(): boolean;
    set is2D(value: boolean);
    /**
     * 2D platformer mode flag.
     *
     * When enabled, the body is constrained to move only on the X+Y plane:
     * - X axis: left/right movement
     * - Y axis: jump/gravity
     * - Z axis: locked (no movement)
     *
     * Use for side-scrolling platformer games like Mario.
     *
     * @type {boolean}
     *
     * @example
     * // Enable 2D mode for a platformer character
     * playerBody.is2D = true;
     *
     * // Check if body is in 2D mode
     * if (playerBody.is2D) {
     *   // Handle 2D-specific logic
     * }
     */
    get is2D(): boolean;
    set collisionType(value: number);
    /**
     * Collision type for Dynamic ↔ Dynamic collision detection.
     *
     * Controls the algorithm used for detecting collisions between dynamic bodies.
     * Use BodyCollisionType constants or set to AUTO for automatic detection.
     *
     * Performance (fastest to most accurate):
     * - BodyCollisionType.SPHERE: O(1) - SDF sphere-sphere test
     * - BodyCollisionType.CAPSULE: O(1) - SDF capsule-capsule test
     * - BodyCollisionType.BOX: O(log n) - BVH-to-Box collision
     * - BodyCollisionType.FULL: O(n log n) - Full BVH-to-BVH collision
     *
     * @type {number}
     *
     * @example
     * import { BodyCollisionType } from '@three-blocks/pro';
     *
     * // Fast sphere collision
     * sphereBody.collisionType = BodyCollisionType.SPHERE;
     *
     * // Capsule collision for characters
     * playerBody.collisionType = BodyCollisionType.CAPSULE;
     *
     * // BVH-to-Box for most convex shapes
     * boxBody.collisionType = BodyCollisionType.BOX;
     *
     * // Full BVH for complex geometry
     * complexBody.collisionType = BodyCollisionType.FULL;
     */
    get collisionType(): number;
    set contactSkin(value: number);
    /**
     * Contact skin margin for ground detection.
     *
     * Expands the ground detection radius beyond actual penetration to maintain
     * stable ground contact. Prevents Y velocity oscillation when resting on surfaces.
     *
     * @type {number}
     * @default 0.01 (1cm)
     *
     * @example
     * // Increase for larger characters or rough terrain
     * playerBody.contactSkin = 0.02;
     *
     * // Decrease for precise platforming
     * playerBody.contactSkin = 0.005;
     */
    get contactSkin(): number;
    set canSleep(value: boolean);
    /**
     * Whether this body can automatically sleep when stationary.
     *
     * When enabled, the body will automatically sleep after remaining
     * stationary (low velocity and position delta) for `sleepDelay` seconds.
     * Sleeping bodies skip physics calculations but can still be collided
     * with and woken up by active bodies.
     *
     * @type {boolean}
     * @default true
     *
     * @example
     * // Disable auto-sleep for player (always active)
     * playerBody.canSleep = false;
     *
     * // Enable for NPCs (default)
     * npcBody.canSleep = true;
     */
    get canSleep(): boolean;
    set sleepVelocityThreshold(value: number);
    /**
     * Velocity magnitude below which the body starts the sleep timer.
     *
     * The body must have velocity below this threshold AND position delta
     * below `sleepPositionThreshold` to start accumulating sleep time.
     *
     * @type {number}
     * @default 0.1
     *
     * @example
     * // More sensitive sleep detection
     * body.sleepVelocityThreshold = 0.05;
     *
     * // Less sensitive (body must be nearly stopped)
     * body.sleepVelocityThreshold = 0.01;
     */
    get sleepVelocityThreshold(): number;
    set sleepPositionThreshold(value: number);
    /**
     * Position delta magnitude below which the body starts the sleep timer.
     *
     * The body must have position delta below this threshold AND velocity
     * below `sleepVelocityThreshold` to start accumulating sleep time.
     *
     * @type {number}
     * @default 0.01
     *
     * @example
     * // More sensitive sleep detection
     * body.sleepPositionThreshold = 0.005;
     */
    get sleepPositionThreshold(): number;
    set sleepDelay(value: number);
    /**
     * Seconds of stillness required before the body sleeps.
     *
     * The body must remain stationary (below velocity and position thresholds)
     * for this duration before entering sleep state.
     *
     * @type {number}
     * @default 0.5
     *
     * @example
     * // Quick sleep (useful for many falling objects)
     * body.sleepDelay = 0.2;
     *
     * // Delayed sleep (more responsive to small movements)
     * body.sleepDelay = 1.0;
     */
    get sleepDelay(): number;
    /**
     * Current sleep state of the body.
     *
     * - 0 = Awake (active physics)
     * - 1 = Drowsy (transitioning to sleep)
     * - 2 = Sleeping (physics skipped)
     *
     * Read-only - controlled by the physics engine.
     * Use this for visual feedback (e.g., color-coding sleeping bodies).
     *
     * @type {number}
     * @readonly
     *
     * @example
     * // Update mesh color based on sleep state
     * if (body.sleepState === 2) {
     *   mesh.material.color.setHex(0x555566); // gray
     * } else if (body.sleepState === 1) {
     *   mesh.material.color.setHex(0x888899); // transitioning
     * } else {
     *   mesh.material.color.setHex(0x44aaff); // awake
     * }
     */
    readonly get sleepState(): number;
    /**
     * Whether the body is currently sleeping.
     *
     * Convenience getter that returns true when sleepState === 2.
     *
     * @type {boolean}
     * @readonly
     */
    readonly get isSleeping(): boolean;
    /**
     * Manually wake up a sleeping body.
     *
     * The body will remain awake until it becomes stationary again
     * (if canSleep is enabled). Use this when applying external forces
     * or when you need to ensure a body is active.
     *
     * @example
     * // Wake up body before applying force
     * body.wake();
     * body.applyImpulse(impulseVector);
     *
     * // Wake all sleeping bodies
     * for (const body of dynamicBodies) {
     *   if (body.isSleeping) body.wake();
     * }
     */
    wake(): void;
    /**
     * Manually put a body to sleep.
     *
     * The body will immediately enter sleep state and skip physics
     * calculations. It will wake up when collided with by an active
     * body or when wake() is called.
     *
     * Only works if canSleep is enabled for this body.
     *
     * @example
     * // Force sleep on distant bodies
     * if (distanceToPlayer > 100) {
     *   body.forceSleep();
     * }
     */
    forceSleep(): void;
}
export default DynamicBody;
import { Body } from './Body.js';
import { Navigation } from '../navigation/Navigation.js';
